function HotspotPanel({ type, onClose }: { type: HotspotType; onClose: () => void }) {
  const meta = hotspotMeta[type];
  switch (type) {
    case "hand":
      return <TimerPanel onClose={onClose} />;
    case "mouth":
      return <QuotePanel onClose={onClose} />;
    case "desk":
      return <CatalogPanel onClose={onClose} />;
    case "candle":
      return <StoriesPanel onClose={onClose} />;
    case "books":
      return <RecommendPanel onClose={onClose} />;
  }
}

// 1. 修身计时器
function TimerPanel({ onClose }: { onClose: () => void }) {
  const [seconds, setSeconds] = useState(0);
  const [running, setRunning] = useState(false);
  const addCultivation = useGameStore((s) => s.addCultivation);
  const totalMin = useGameStore((s) => s.cultivationMinutes);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (running) {
      intervalRef.current = setInterval(() => {
        setSeconds((s) => s + 1);
      }, 1000);
    } else if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [running]);

  const handleStop = () => {
    setRunning(false);
    const min = Math.floor(seconds / 60);
    if (min > 0) addCultivation(min);
  };

  const handleReset = () => {
    setRunning(false);
    setSeconds(0);
  };

  const mm = String(Math.floor(seconds / 60)).padStart(2, "0");
  const ss = String(seconds % 60).padStart(2, "0");
  const progress = (seconds % 60) / 60;

  return (
    <PanelShell title="修身计时器" icon={Clock} onClose={onClose}>
      <p className="mb-6 text-center font-serif text-sm text-ink/70">
        吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？
      </p>

      {/* 计时圆环 */}
      <div className="flex flex-col items-center">
        <div className="relative h-56 w-56">
          <svg viewBox="0 0 100 100" className="h-full w-full -rotate-90">
            <circle cx="50" cy="50" r="44" fill="none" stroke="#e8dcc0" strokeWidth="4" />
            <circle
              cx="50" cy="50" r="44" fill="none" stroke="#c8423f" strokeWidth="4"
              strokeDasharray={`${2 * Math.PI * 44}`}
              strokeDashoffset={`${2 * Math.PI * 44 * (1 - progress)}`}
              strokeLinecap="round"
              style={{ transition: "stroke-dashoffset 1s linear" }}
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="font-brush text-5xl text-ink">{mm}:{ss}</span>
            <span className="mt-1 font-serif text-xs text-wood">分:秒</span>
          </div>
        </div>

        {/* 控制按钮 */}
        <div className="mt-6 flex gap-3">
          {!running ? (
            <button onClick={() => setRunning(true)} className="btn-gold">
              <Play size={16} /> 开始修身
            </button>
          ) : (
            <button onClick={() => setRunning(false)} className="btn-outline">
              <Pause size={16} /> 暂停
            </button>
          )}
          <button onClick={handleStop} className="btn-outline">
            完成 · 存档
          </button>
          <button onClick={handleReset} className="btn-outline">
            <RotateCcw size={16} />
          </button>
        </div>

        {/* 累计统计 */}
        <div className="mt-8 w-full rounded-lg border border-gold/20 bg-paper-light/50 p-4 text-center">
          <div className="font-serif text-xs text-wood">累计修身时长</div>
          <div className="mt-1 font-brush text-3xl text-cinnabar">{totalMin} 分钟</div>
          <div className="mt-1 font-serif text-[10px] text-wood">
            {totalMin >= 60 ? `约 ${(totalMin / 60).toFixed(1)} 时` : "继续努力，日积月累"}
          </div>
        </div>
      </div>
    </PanelShell>
  );
}

// 2. 修身金句
function QuotePanel({ onClose }: { onClose: () => void }) {
  const [idx, setIdx] = useState(() => Math.floor(Math.random() * quotes.length));
  const [copied, setCopied] = useState(false);
  const collected = useGameStore((s) => s.collectedQuotes);
  const collectQuote = useGameStore((s) => s.collectQuote);

  const quote = quotes[idx];
  const figure = getFigure(quote.figureId);
  const isCollected = collected.includes(quote.id);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(`「${quote.text}」—— ${quote.source}`);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // 兜底
      setCopied(false);
    }
  };

  const handleShare = async () => {
    collectQuote(quote.id);
    if (navigator.share) {
      try {
        await navigator.share({
          title: "古今寰宇 · 修身金句",
          text: `「${quote.text}」—— ${quote.source}`,
        });
      } catch {
        // 用户取消
      }
    } else {
      handleCopy();
    }
  };

  const next = () => setIdx((i) => (i + 1) % quotes.length);

  return (
    <PanelShell title="修身金句" icon={Quote} onClose={onClose}>
      <div className="space-y-6">
        {/* 金句卡片 */}
        <motion.div
          key={quote.id}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="relative rounded-xl border border-gold/30 bg-paper-light/60 p-8"
        >
          {/* 引号装饰 */}
          <div className="absolute left-4 top-2 font-brush text-6xl text-gold/30">"</div>
          <div className="absolute bottom-0 right-4 font-brush text-6xl text-gold/30">"</div>

          <p className="relative font-serif text-xl leading-relaxed text-ink">
            {quote.text}
          </p>
          <div className="mt-4 flex items-center justify-between">
            <div>
              <div className="font-serif text-sm text-cinnabar">—— {quote.source}</div>
              {figure && (
                <div className="mt-1 font-serif text-xs text-wood">
                  {figure.name}{figure.courtesyName ? ` · 字${figure.courtesyName}` : ""}
                </div>
              )}
            </div>
            {isCollected && <span className="seal">已收藏</span>}
          </div>
        </motion.div>

        {/* 释义 */}
        <div className="rounded-lg border border-celadon/30 bg-celadon/5 p-4">
          <div className="mb-1 font-serif text-xs font-semibold text-celadon">现代释义</div>
          <p className="font-serif text-sm leading-relaxed text-ink/80">{quote.meaning}</p>
        </div>

        {/* 操作 */}
        <div className="flex flex-wrap items-center justify-center gap-3">
          <button onClick={next} className="btn-gold">
            换一句
          </button>
          <button onClick={handleCopy} className="btn-outline">
            <Copy size={16} /> {copied ? "已复制" : "复制"}
          </button>
          <button onClick={handleShare} className="btn-outline">
            <Share2 size={16} /> {navigator.share ? "分享" : "收藏"}
          </button>
        </div>

        {/* 收藏列表 */}
        {collected.length > 0 && (
          <div>
            <div className="mb-2 font-serif text-xs text-wood">已收藏 {collected.length} 句</div>
            <div className="flex flex-wrap gap-2">
              {collected.map((id) => {
                const q = quotes.find((x) => x.id === id);
                if (!q) return null;
                return (
                  <span
                    key={id}
                    className="rounded-full border border-gold/20 bg-gold/5 px-3 py-1 font-serif text-[10px] text-ink/70"
                  >
                    {q.text.slice(0, 12)}...
                  </span>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </PanelShell>
  );
}

