const oralNarrations: Record<string, string> = {
  rec_lunyu: "老朽常言，朱子集注，乃宋儒理学之大成。朱熹集前贤之说，注《论语》二十篇，字字斟酌，句句考究。后世科举取士，皆以此为本。汝若欲明圣贤之意，不可不读此书。",
  rec_mengzi: "孟子者，亚圣也。其书七篇，论仁政、说性善，气势磅礴。'民为贵，社稷次之，君为轻'，此言震古烁今。与《论语》并称'论孟'，为儒家四书之一，修身治国皆在其中。",
  rec_daxue: "《大学》一书，曾子所述。开篇即言'大学之道，在明明德，在亲民，在止于至善'。修身、齐家、治国、平天下，次第分明，内圣外王之道尽矣。四书之首，入门之径也。",
  rec_zhongyong: "子思作《中庸》，论'不偏之谓中，不易之谓庸'。喜怒哀乐之未发谓之中，发而皆中节谓之和。此书论心性修养，至精至微。学者当静心体悟，方知其中滋味。",
  rec_zhuangzi: "庄周之文，汪洋恣肆，意出尘外。'北冥有鱼，其名为鲲'，逍遥游一篇，开精神自由之境。读《庄子》当放下尘世牵挂，随其想象翱翔，方得逍遥真意。",
  rec_yijing: "《易经》者，群经之首也。伏羲画卦，文王演卦，孔子作传。'太极生两仪，两仪生四象'，变易之理尽在其中。中华文明之源，百家之宗，不可不究。",
};

function RecommendPanel({ onClose }: { onClose: () => void }) {
  const [narrating, setNarrating] = useState<string | null>(null);

  return (
    <PanelShell title="典籍推荐" icon={Layers} onClose={onClose}>
      {/* 师者引言 */}
      <div className="mb-5 rounded-lg border border-cinnabar/20 bg-cinnabar/5 p-4">
        <div className="mb-1 flex items-center gap-2">
          <span className="font-brush text-lg text-cinnabar">师者云</span>
          <span className="text-[10px] text-wood">· 卷轴口述</span>
        </div>
        <p className="font-serif text-sm leading-relaxed text-ink/80">
          老朽于这书房之中，常伴竹简青灯。今日汝来，老朽便将毕生所读之典籍，一一口述于汝。
          汝且静听，择其善者而从之。
        </p>
      </div>

      <div className="space-y-3">
        {recommendations.map((r) => {
          const dynasty = getDynasty(r.dynastyId);
          const isOpen = narrating === r.id;
          const narration = oralNarrations[r.id] || r.reason;
          return (
            <div
              key={r.id}
              className="rounded-lg border border-gold/20 bg-paper-light/50 overflow-hidden transition-colors hover:border-gold/40"
            >
              <button
                onClick={() => setNarrating(isOpen ? null : r.id)}
                className="flex w-full items-center justify-between p-4 text-left"
              >
                <div className="flex items-center gap-3">
                  <span className="font-brush text-3xl text-gold/40">卷</span>
                  <div>
                    <h3 className="font-brush text-2xl text-ink">{r.name}</h3>
                    <div className="mt-0.5 flex items-center gap-2">
                      {r.author && (
                        <span className="font-serif text-xs text-wood">{r.author} 撰</span>
                      )}
                      <span
                        className="rounded-full px-2 py-0.5 font-serif text-[10px]"
                        style={{ backgroundColor: `${dynasty?.color}30`, color: dynasty?.color }}
                      >
                        {dynasty?.name}
                      </span>
                    </div>
                  </div>
                </div>
                <span className={`text-gold transition-transform ${isOpen ? "rotate-90" : ""}`}>→</span>
              </button>
              <AnimatePresence>
                {isOpen && (
                  <motion.div
                    initial={{ height: 0 }}
                    animate={{ height: "auto" }}
                    exit={{ height: 0 }}
                    className="overflow-hidden"
                  >
                    <div className="border-t border-gold/10 p-4">
                      {/* 口述内容 */}
                      <div className="relative rounded bg-ink-dark/5 p-4 pl-8">
                        <span className="absolute left-2 top-1 font-brush text-3xl text-cinnabar/30">「</span>
                        <p className="font-serif text-sm leading-loose text-ink/85">
                          {narration}
                        </p>
                      </div>
                      {/* 要义 */}
                      <div className="mt-3 flex items-start gap-2">
                        <span className="mt-0.5 shrink-0 rounded bg-gold/15 px-1.5 py-0.5 font-serif text-[10px] text-gold">要义</span>
                        <p className="font-serif text-xs leading-relaxed text-ink/60">{r.reason}</p>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          );
        })}
      </div>

      <div className="mt-6 text-center">
        <Link to="/relics" className="btn-outline">
          前往文物建筑馆 →
        </Link>
      </div>
    </PanelShell>
  );
}
