import { useParams, Link } from "react-router-dom";
import { motion } from "framer-motion";
import { ArrowLeft, Quote } from "lucide-react";
import NavBar from "@/components/NavBar";
import FigurePortrait from "@/components/FigurePortrait";
import RelicThumb from "@/components/RelicThumb";
import { getFigure, getDynasty, getQuote, getRelic, figures } from "@/data";

export default function FigureDetail() {
  const { id } = useParams();
  const figure = id ? getFigure(id) : undefined;

  if (!figure) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-ink-wash">
        <div className="text-center">
          <p className="font-serif text-paper/60">未找到该人物</p>
          <Link to="/figures" className="btn-outline mt-4">
            返回图鉴
          </Link>
        </div>
      </div>
    );
  }

  const dynasty = getDynasty(figure.dynastyId);
  const figureQuotes = figure.quoteIds.map(getQuote).filter(Boolean);
  const figureRelics = figure.relicIds.map(getRelic).filter(Boolean);
  const sameDynastyFigures = figures.filter(
    (f) => f.dynastyId === figure.dynastyId && f.id !== figure.id
  );

  return (
    <div className="relative min-h-screen bg-ink-wash">
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-20" />

      <NavBar />

      <div className="mx-auto max-w-5xl px-6 pt-32 pb-24">
        {/* 返回 */}
        <Link
          to="/figures"
          className="mb-8 inline-flex items-center gap-2 font-serif text-sm text-paper/60 transition-colors hover:text-gold"
        >
          <ArrowLeft size={16} /> 返回人物图鉴
        </Link>

        {/* 人物头部 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="scroll-card mb-8 grid grid-cols-1 overflow-hidden md:grid-cols-[auto_1fr]"
        >
          {/* 画像 */}
          <div className="flex items-center justify-center bg-gradient-to-br from-ink-dark/20 to-wood/20 p-8">
            <FigurePortrait
              name={figure.name}
              title={figure.title}
              hue={figure.imageHue}
              size="xl"
              imagePrompt={figure.image}
            />
          </div>

          {/* 信息 */}
          <div className="p-8">
            <div className="mb-3 flex items-center gap-3">
              <span
                className="rounded-full px-3 py-0.5 font-serif text-xs"
                style={{ backgroundColor: `${dynasty?.color}30`, color: dynasty?.color }}
              >
                {dynasty?.name}
              </span>
              <span className="font-serif text-xs text-wood">{figure.era}</span>
              <span className="font-serif text-xs text-wood">{figure.country}</span>
            </div>

            <h1 className="font-brush text-6xl text-ink">{figure.name}</h1>
            {figure.courtesyName && (
              <p className="mt-1 font-serif text-sm text-wood">字 {figure.courtesyName}</p>
            )}
            <p className="mt-1 font-serif text-base text-cinnabar">{figure.title}</p>

            <div className="my-4 h-px bg-gold/30" />

            <p className="font-serif text-sm leading-relaxed text-ink/80">{figure.bio}</p>
          </div>
        </motion.div>

        {/* 主要成就 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="scroll-card mb-8 p-8"
        >
          <h2 className="mb-4 font-brush text-3xl text-cinnabar">主要成就</h2>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            {figure.achievements.map((a, i) => (
              <div
                key={i}
                className="flex items-start gap-3 rounded-lg border border-gold/20 bg-paper-light/50 p-3"
              >
                <div className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-gold/20 font-brush text-sm text-gold">
                  {i + 1}
                </div>
                <p className="font-serif text-sm text-ink/80">{a}</p>
              </div>
            ))}
          </div>
        </motion.div>

        {/* 修身金句 */}
        {figureQuotes.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="scroll-card mb-8 p-8"
          >
            <h2 className="mb-4 font-brush text-3xl text-cinnabar">修身金句</h2>
            <div className="space-y-4">
              {figureQuotes.map((q) =>
                q ? (
                  <div
                    key={q.id}
                    className="relative rounded-lg border border-gold/20 bg-paper-light/50 p-4"
                  >
                    <Quote className="absolute right-3 top-3 text-gold/30" size={20} />
                    <p className="font-serif text-base text-ink">{q.text}</p>
                    <div className="mt-2 font-serif text-xs text-cinnabar">—— {q.source}</div>
                    <p className="mt-2 font-serif text-xs text-ink/60">{q.meaning}</p>
                  </div>
                ) : null
              )}
            </div>
          </motion.div>
        )}

        {/* 关联文物 */}
        {figureRelics.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="scroll-card p-8"
          >
            <h2 className="mb-4 font-brush text-3xl text-cinnabar">关联文物 / 建筑</h2>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              {figureRelics.map((r) =>
                r ? (
                  <Link key={r.id} to={`/relics/${r.id}`}>
                    <RelicThumb
                      name={r.name}
                      hue={r.imageHue}
                      type={r.type}
                      category={r.category}
                      imagePrompt={r.name}
                    />
                  </Link>
                ) : null
              )}
            </div>
          </motion.div>
        )}

        {/* 同时代人物 */}
        {sameDynastyFigures.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 }}
            className="scroll-card mt-8 p-8"
          >
            <h2 className="mb-4 font-brush text-3xl text-cinnabar">同时代人物</h2>
            <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
              {sameDynastyFigures.slice(0, 6).map((f) => (
                <Link key={f.id} to={`/figures/${f.id}`} className="text-center">
                  <FigurePortrait
                    name={f.name}
                    title={f.title}
                    hue={f.imageHue}
                    size="md"
                    imagePrompt={f.image}
                  />
                  <div className="mt-2 font-serif text-xs text-ink/70">{f.era}</div>
                </Link>
              ))}
            </div>
          </motion.div>
        )}
      </div>
    </div>
  );
}
