import { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { motion } from "framer-motion";
import { ArrowLeft, MapPin } from "lucide-react";
import NavBar from "@/components/NavBar";
import FigurePortrait from "@/components/FigurePortrait";
import RelicThumb from "@/components/RelicThumb";
import { getRelic, getDynasty, getFigure, markers, relics } from "@/data";
import { relicUrl } from "@/lib/image";

export default function RelicDetail() {
  const { id } = useParams();
  const relic = id ? getRelic(id) : undefined;

  if (!relic) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-ink-wash">
        <div className="text-center">
          <p className="font-serif text-paper/60">未找到该文物</p>
          <Link to="/relics" className="btn-outline mt-4">
            返回文物馆
          </Link>
        </div>
      </div>
    );
  }

  const dynasty = getDynasty(relic.dynastyId);
  const relatedFigures = figuresForRelic(relic.id);
  const relatedMarker = markers.find((m) => m.relicIds.includes(relic.id));
  const sameDynastyRelics = relics.filter(
    (r) => r.dynastyId === relic.dynastyId && r.id !== relic.id
  );

  return (
    <div className="relative min-h-screen bg-ink-wash">
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-20" />

      <NavBar />

      <div className="mx-auto max-w-5xl px-6 pt-32 pb-24">
        {/* 返回 */}
        <Link
          to="/relics"
          className="mb-8 inline-flex items-center gap-2 font-serif text-sm text-paper/60 transition-colors hover:text-gold"
        >
          <ArrowLeft size={16} /> 返回文物建筑馆
        </Link>

        {/* 头部 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="scroll-card mb-8 overflow-hidden"
        >
          {/* 大图区 - AI 生图 + 薄材质 */}
          <RelicHeaderImage relic={relic} dynastyColor={dynasty?.color} dynastyName={dynasty?.name} />


          {/* 信息区 */}
          <div className="p-8">
            <div className="mb-6 flex items-center gap-3">
              <MapPin size={16} className="text-cinnabar" />
              <span className="font-serif text-sm text-ink/70">{relic.locationName}</span>
              {relic.country === "中国" ? (
                <span className="seal">中国</span>
              ) : (
                <span className="seal" style={{ backgroundColor: "#4a90c4" }}>世界</span>
              )}
            </div>

            <h2 className="mb-3 font-brush text-2xl text-cinnabar">文物简介</h2>
            <p className="mb-6 font-serif text-sm leading-relaxed text-ink/80">
              {relic.description}
            </p>

            <h2 className="mb-3 font-brush text-2xl text-cinnabar">历史沿革</h2>
            <p className="font-serif text-sm leading-relaxed text-ink/80">{relic.history}</p>
          </div>
        </motion.div>

        {/* 关联人物 */}
        {relatedFigures.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="scroll-card mb-8 p-8"
          >
            <h2 className="mb-4 font-brush text-3xl text-cinnabar">关联人物</h2>
            <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
              {relatedFigures.map((f) => (
                <Link key={f.id} to={`/figures/${f.id}`} className="text-center">
                  <FigurePortrait
                    name={f.name}
                    title={f.title}
                    hue={f.imageHue}
                    size="md"
                    imagePrompt={f.image}
                  />
                  <div className="mt-2 font-serif text-xs text-ink/70">{f.era}</div>
                </Link>
              ))}
            </div>
          </motion.div>
        )}

        {/* 同时代文物 */}
        {sameDynastyRelics.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.15 }}
            className="scroll-card mb-8 p-8"
          >
            <h2 className="mb-4 font-brush text-3xl text-cinnabar">同时代文物</h2>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              {sameDynastyRelics.slice(0, 6).map((r) => (
                <Link key={r.id} to={`/relics/${r.id}`}>
                  <RelicThumb
                    name={r.name}
                    hue={r.imageHue}
                    type={r.type}
                    category={r.category}
                    imagePrompt={r.name}
                  />
                </Link>
              ))}
            </div>
          </motion.div>
        )}

        {/* 地球入口 */}
        {relatedMarker && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="scroll-card p-8 text-center"
          >
            <h2 className="mb-2 font-brush text-3xl text-cinnabar">在地球上查看</h2>
            <p className="mb-4 font-serif text-sm text-ink/70">
              前往寰宇地球，查看 {relatedMarker.name} 的地理位置
            </p>
            <Link to="/globe" className="btn-gold">
              前往寰宇地球
            </Link>
          </motion.div>
        )}
      </div>
    </div>
  );
}

// 找出与该文物关联的人物
import { figures, type Relic } from "@/data";
function figuresForRelic(relicId: string) {
  return figures.filter((f) => f.relicIds.includes(relicId));
}

// 文物大图头部 - AI 生图 + 薄材质
function RelicHeaderImage({
  relic,
  dynastyColor,
  dynastyName,
}: {
  relic: Relic;
  dynastyColor?: string;
  dynastyName?: string;
}) {
  const [imgError, setImgError] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const url = relicUrl(relic.name);
  const showImg = url && !imgError;

  return (
    <div
      className="relative h-80 overflow-hidden"
      style={{
        background: `linear-gradient(135deg, ${relic.imageHue}aa 0%, ${relic.imageHue}66 50%, ${relic.imageHue}33 100%)`,
      }}
    >
      {/* AI 生图 */}
      {showImg && (
        <>
          {!imgLoaded && (
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="font-serif text-sm text-paper/40">图片加载中...</div>
            </div>
          )}
          <img
            src={url}
            alt={relic.name}
            loading="lazy"
            onLoad={() => setImgLoaded(true)}
            onError={() => setImgError(true)}
            className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-700 ${
              imgLoaded ? "opacity-80" : "opacity-0"
            }`}
          />
        </>
      )}

      {/* 薄材质玻璃覆层 */}
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-ink-dark/90 via-ink-dark/20 to-white/5" />
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-15" />
      <div className="absolute inset-6 rounded border border-white/10" />

      {/* 印章 */}
      <div className="absolute left-6 top-6">
        <span className="seal backdrop-blur-sm">{relic.type}</span>
      </div>

      {/* 底部标题 */}
      <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-ink-dark/80 to-transparent p-6 backdrop-blur-[2px]">
        <div className="mb-2 flex items-center gap-3">
          <span
            className="rounded-full px-3 py-0.5 font-serif text-xs"
            style={{ backgroundColor: `${dynastyColor}30`, color: dynastyColor }}
          >
            {dynastyName}
          </span>
          <span className="font-serif text-xs text-paper/60">{relic.category}</span>
          {relic.material && (
            <span className="font-serif text-xs text-paper/60">{relic.material}</span>
          )}
        </div>
        <h1 className="font-brush text-5xl text-paper-light drop-shadow-lg">{relic.name}</h1>
      </div>
    </div>
  );
}
