import { Link, useLocation } from "react-router-dom";
import { cn } from "@/lib/utils";

const navItems = [
  { path: "/", label: "大厅", icon: "◆" },
  { path: "/globe", label: "寰宇", icon: "◯" },
  { path: "/study", label: "书房", icon: "卍" },
  { path: "/timeline", label: "长河", icon: "═" },
  { path: "/figures", label: "人物", icon: "人" },
  { path: "/relics", label: "文物", icon: "◎" },
];

export default function NavBar() {
  const location = useLocation();

  return (
    <nav className="fixed left-1/2 top-6 z-50 -translate-x-1/2">
      <div className="flex items-center gap-1 rounded-full border border-gold/30 bg-ink-dark/80 px-2 py-1.5 backdrop-blur-xl shadow-glow">
        {navItems.map((item) => {
          const active = location.pathname === item.path ||
            (item.path !== "/" && location.pathname.startsWith(item.path));
          return (
            <Link
              key={item.path}
              to={item.path}
              className={cn(
                "flex items-center gap-1.5 rounded-full px-4 py-1.5 font-serif text-sm transition-all duration-300",
                active
                  ? "bg-gold-gradient text-ink-dark shadow-glow"
                  : "text-paper/70 hover:text-gold hover:bg-gold/10"
              )}
            >
              <span className={cn("text-xs", active ? "opacity-90" : "opacity-50")}>
                {item.icon}
              </span>
              <span>{item.label}</span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}
