import { create } from "zustand";
import { persist } from "zustand/middleware";

export type UserRole = "roamer" | "scholar" | "lecturer";

interface GameState {
  // 用户角色
  role: UserRole;
  // 已访问地球标记
  visitedMarkers: string[];
  // 已访问国家
  visitedCountries: string[];
  // 收藏金句
  collectedQuotes: string[];
  // 修身累计分钟
  cultivationMinutes: number;
  // 今日是否已打卡
  lastVisitDate: string;

  // 操作
  setRole: (role: UserRole) => void;
  visitMarker: (id: string) => void;
  visitCountry: (id: string) => void;
  collectQuote: (id: string) => void;
  removeQuote: (id: string) => void;
  addCultivation: (min: number) => void;
  resetProgress: () => void;
}

const today = () => new Date().toISOString().slice(0, 10);

export const useGameStore = create<GameState>()(
  persist(
    (set) => ({
      role: "roamer",
      visitedMarkers: [],
      visitedCountries: [],
      collectedQuotes: [],
      cultivationMinutes: 0,
      lastVisitDate: "",

      setRole: (role) => set({ role }),

      visitMarker: (id) =>
        set((state) => ({
          visitedMarkers: state.visitedMarkers.includes(id)
            ? state.visitedMarkers
            : [...state.visitedMarkers, id],
          lastVisitDate: today(),
        })),

      visitCountry: (id) =>
        set((state) => ({
          visitedCountries: state.visitedCountries.includes(id)
            ? state.visitedCountries
            : [...state.visitedCountries, id],
          lastVisitDate: today(),
        })),

      collectQuote: (id) =>
        set((state) => ({
          collectedQuotes: state.collectedQuotes.includes(id)
            ? state.collectedQuotes
            : [...state.collectedQuotes, id],
        })),

      removeQuote: (id) =>
        set((state) => ({
          collectedQuotes: state.collectedQuotes.filter((q) => q !== id),
        })),

      addCultivation: (min) =>
        set((state) => ({
          cultivationMinutes: state.cultivationMinutes + min,
        })),

      resetProgress: () =>
        set({
          visitedMarkers: [],
          visitedCountries: [],
          collectedQuotes: [],
          cultivationMinutes: 0,
          lastVisitDate: "",
        }),
    }),
    {
      name: "guangjin-huanyu-archive",
    }
  )
);
