import { useState, Suspense } from "react";
import { Link } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { MapPin, X, Check, Footprints, Navigation, Globe2, Map } from "lucide-react";
import GlobeScene from "@/components/GlobeScene";
import NavBar from "@/components/NavBar";
import { markers, countries, getRelic, getFigure, getDynasty, type Marker, type Country } from "@/data";
import { useGameStore } from "@/store/gameStore";
import { portraitUrl, relicUrl } from "@/lib/image";

export default function Globe() {
  const [selected, setSelected] = useState<Marker | null>(null);
  const [hovered, setHovered] = useState<Marker | null>(null);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [hoveredCountry, setHoveredCountry] = useState<Country | null>(null);
  const [showFootprint, setShowFootprint] = useState(false);
  const [mode, setMode] = useState<"country" | "detail">("country");

  const visitedMarkers = useGameStore((s) => s.visitedMarkers);
  const visitMarker = useGameStore((s) => s.visitMarker);
  const visitedCountries = useGameStore((s) => s.visitedCountries);
  const visitCountry = useGameStore((s) => s.visitCountry);

  const handleMarkerClick = (m: Marker) => {
    setSelected(m);
    visitMarker(m.id);
  };

  const handleCountryClick = (c: Country) => {
    setSelectedCountry(c);
    visitCountry(c.id);
  };

  const visitedCount = mode === "country" ? visitedCountries.length : visitedMarkers.length;
  const totalCount = mode === "country" ? countries.length : markers.length;
  const progress = Math.round((visitedCount / totalCount) * 100);

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-ink-dark">
      {/* 3D 地球 */}
      <div className="absolute inset-0">
        <Suspense
          fallback={
            <div className="flex h-full items-center justify-center">
              <div className="font-serif text-gold/60">地球加载中...</div>
            </div>
          }
        >
          <GlobeScene
            onMarkerClick={handleMarkerClick}
            onMarkerHover={setHovered}
            visitedIds={visitedMarkers}
            onCountryClick={handleCountryClick}
            onCountryHover={setHoveredCountry}
            visitedCountryIds={visitedCountries}
            showCountries={mode === "country"}
          />
        </Suspense>
      </div>

      <NavBar />

      {/* 顶部标题 + 模式切换 */}
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="pointer-events-none absolute left-8 top-24"
      >
        <h1 className="font-brush text-5xl text-gold text-glow-gold">寰宇地球</h1>
        <p className="mt-1 font-serif text-sm text-paper/60">
          {mode === "country"
            ? "点击国家板块 · 探索各国历史"
            : "拖拽旋转 · 滚轮缩放 · 点击标记探索"}
        </p>
      </motion.div>

      {/* 模式切换按钮 */}
      <div className="absolute right-8 top-24 flex gap-2">
        <button
          onClick={() => { setMode("country"); setSelected(null); }}
          className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 backdrop-blur-md transition-all ${
            mode === "country"
              ? "border-gold bg-gold/20 text-gold"
              : "border-gold/30 bg-ink-dark/70 text-paper/60 hover:text-gold"
          }`}
        >
          <Globe2 size={14} />
          <span className="font-serif text-xs">国家</span>
        </button>
        <button
          onClick={() => { setMode("detail"); setSelectedCountry(null); }}
          className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 backdrop-blur-md transition-all ${
            mode === "detail"
              ? "border-gold bg-gold/20 text-gold"
              : "border-gold/30 bg-ink-dark/70 text-paper/60 hover:text-gold"
          }`}
        >
          <Map size={14} />
          <span className="font-serif text-xs">遗址</span>
        </button>
      </div>

      {/* 悬停提示 */}
      <AnimatePresence>
        {mode === "country" && hoveredCountry && !selectedCountry && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="pointer-events-none absolute bottom-32 left-1/2 -translate-x-1/2"
          >
            <div className="flex items-center gap-2 rounded-full border border-gold/30 bg-ink-dark/80 px-4 py-2 backdrop-blur-md">
              <Navigation size={14} className="text-gold" />
              <span className="font-serif text-sm text-paper">{hoveredCountry.name}</span>
              <span className="font-serif text-[10px] text-wood">· {hoveredCountry.era}</span>
            </div>
          </motion.div>
        )}
        {mode === "detail" && hovered && !selected && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="pointer-events-none absolute bottom-32 left-1/2 -translate-x-1/2"
          >
            <div className="flex items-center gap-2 rounded-full border border-gold/30 bg-ink-dark/80 px-4 py-2 backdrop-blur-md">
              <Navigation size={14} className="text-gold" />
              <span className="font-serif text-sm text-paper">{hovered.name}</span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 足迹面板按钮 */}
      <button
        onClick={() => setShowFootprint(true)}
        className="absolute right-8 top-40 flex items-center gap-2 rounded-full border border-gold/40 bg-ink-dark/70 px-4 py-2 backdrop-blur-md transition-all hover:border-gold hover:bg-gold/10"
      >
        <Footprints size={16} className="text-gold" />
        <span className="font-serif text-sm text-paper">足迹</span>
        <span className="rounded-full bg-gold/20 px-2 py-0.5 text-xs text-gold">
          {visitedCount}/{totalCount}
        </span>
      </button>

      {/* 进度条 + 图例 */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2">
        <div className="mb-2 flex items-center justify-center gap-4">
          <div className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-full bg-cinnabar" />
            <span className="font-serif text-[10px] text-paper/60">中国</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: "#4a90c4" }} />
            <span className="font-serif text-[10px] text-paper/60">外国</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-full bg-gold" />
            <span className="font-serif text-[10px] text-paper/60">已到访</span>
          </div>
        </div>
        <div className="w-72">
          <div className="mb-1 flex justify-between font-serif text-xs text-paper/60">
            <span>{mode === "country" ? "国家探索进度" : "遗址探索进度"}</span>
            <span className="text-gold">{progress}%</span>
          </div>
          <div className="h-1.5 overflow-hidden rounded-full bg-ink-light">
            <motion.div
              className="h-full bg-gold-gradient"
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{ duration: 0.8 }}
            />
          </div>
        </div>
      </div>

      {/* 国家详情弹窗 */}
      <AnimatePresence>
        {selectedCountry && (
          <CountryPopup
            country={selectedCountry}
            visited={visitedCountries.includes(selectedCountry.id)}
            onClose={() => setSelectedCountry(null)}
          />
        )}
      </AnimatePresence>

      {/* 标记详情弹窗 */}
      <AnimatePresence>
        {selected && (
          <MarkerPopup
            marker={selected}
            visited={visitedMarkers.includes(selected.id)}
            onClose={() => setSelected(null)}
          />
        )}
      </AnimatePresence>

      {/* 足迹面板 */}
      <AnimatePresence>
        {showFootprint && (
          <FootprintPanel
            visitedIds={visitedMarkers}
            visitedCountryIds={visitedCountries}
            onClose={() => setShowFootprint(false)}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

// ===== 国家详情弹窗 =====
function CountryPopup({
  country,
  visited,
  onClose,
}: {
  country: Country;
  visited: boolean;
  onClose: () => void;
}) {
  const relics = country.relicIds.map(getRelic).filter(Boolean);
  const figures = country.figureIds.map(getFigure).filter(Boolean);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-40 flex items-center justify-center bg-ink-dark/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.9, y: 20 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.9, y: 20 }}
        onClick={(e) => e.stopPropagation()}
        className="scroll-card relative max-h-[85vh] w-full max-w-3xl overflow-y-auto p-8"
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-full p-1.5 text-ink/60 transition-colors hover:bg-cinnabar/20 hover:text-cinnabar"
        >
          <X size={20} />
        </button>

        {/* 标题 */}
        <div className="mb-4 flex items-center gap-3">
          <span
            className="flex h-12 w-12 items-center justify-center rounded-full font-brush text-2xl text-white shadow-lg"
            style={{ backgroundColor: country.color }}
          >
            {country.name[0]}
          </span>
          <div>
            <h2 className="font-brush text-4xl text-ink">{country.name}</h2>
            <div className="font-serif text-xs text-wood">{country.fullName} · {country.era}</div>
          </div>
          {visited && (
            <span className="seal flex items-center gap-1 ml-auto">
              <Check size={12} /> 已到访
            </span>
          )}
        </div>

        {/* 简介 */}
        <div className="mb-4 rounded-lg border p-4" style={{ borderColor: `${country.color}40`, backgroundColor: `${country.color}08` }}>
          <p className="font-serif text-sm leading-relaxed text-ink/80">{country.intro}</p>
        </div>

        {/* 历史详述 */}
        <div className="mb-6">
          <h3 className="mb-2 font-serif text-sm font-semibold text-ink">历史脉络</h3>
          <p className="font-serif text-sm leading-loose text-ink/70">{country.history}</p>
        </div>

        {/* 人物 */}
        {figures.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-3 font-serif text-sm font-semibold text-ink">
              历史人物 <span className="text-wood">({figures.length})</span>
            </h3>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
              {figures.slice(0, 12).map((f) =>
                f ? (
                  <Link
                    key={f.id}
                    to={`/figures/${f.id}`}
                    className="flex items-center gap-2 rounded-lg border border-gold/20 bg-paper-light/50 p-2 transition-colors hover:border-gold hover:bg-gold/10"
                  >
                    <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full border border-gold/30">
                      <img
                        src={portraitUrl(f.image)}
                        alt={f.name}
                        className="h-full w-full object-cover opacity-85"
                        onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
                      />
                    </div>
                    <div className="min-w-0">
                      <div className="truncate font-serif text-sm font-medium text-ink">{f.name}</div>
                      <div className="truncate text-[10px] text-wood">{f.title}</div>
                    </div>
                  </Link>
                ) : null
              )}
            </div>
            {figures.length > 12 && (
              <div className="mt-2 text-center">
                <Link to="/figures" className="font-serif text-xs text-gold hover:underline">
                  查看全部 {figures.length} 位人物 →
                </Link>
              </div>
            )}
          </div>
        )}

        {/* 文物建筑 */}
        {relics.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-3 font-serif text-sm font-semibold text-ink">
              文物建筑 <span className="text-wood">({relics.length})</span>
            </h3>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
              {relics.slice(0, 12).map((r) =>
                r ? (
                  <Link
                    key={r.id}
                    to={`/relics/${r.id}`}
                    className="overflow-hidden rounded-lg border border-gold/20 bg-paper-light/50 transition-colors hover:border-gold hover:bg-gold/10"
                  >
                    <div className="h-20 w-full overflow-hidden">
                      <img
                        src={relicUrl(r.name)}
                        alt={r.name}
                        className="h-full w-full object-cover opacity-85"
                        onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
                      />
                    </div>
                    <div className="p-2">
                      <div className="truncate font-serif text-xs font-medium text-ink">{r.name}</div>
                      <div className="truncate text-[10px] text-wood">{r.type} · {r.category}</div>
                    </div>
                  </Link>
                ) : null
              )}
            </div>
          </div>
        )}

        {/* 历史遗址 */}
        {country.markerIds.length > 0 && (
          <div>
            <h3 className="mb-3 font-serif text-sm font-semibold text-ink">
              历史遗址 <span className="text-wood">({country.markerIds.length})</span>
            </h3>
            <div className="flex flex-wrap gap-2">
              {country.markerIds.map((mid) => {
                const m = markers.find((x) => x.id === mid);
                if (!m) return null;
                return (
                  <span key={mid} className="rounded-full border border-gold/20 bg-gold/5 px-3 py-1 font-serif text-xs text-ink/70">
                    <MapPin size={10} className="mr-1 inline" />
                    {m.name}
                  </span>
                );
              })}
            </div>
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}

// ===== 标记详情弹窗 =====
function MarkerPopup({
  marker,
  visited,
  onClose,
}: {
  marker: Marker;
  visited: boolean;
  onClose: () => void;
}) {
  const relics = marker.relicIds.map(getRelic).filter(Boolean);
  const figures = marker.figureIds.map(getFigure).filter(Boolean);
  const dynasty = relics[0] ? getDynasty(relics[0]!.dynastyId) : undefined;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-40 flex items-center justify-center bg-ink-dark/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.9, y: 20 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.9, y: 20 }}
        onClick={(e) => e.stopPropagation()}
        className="scroll-card relative max-h-[80vh] w-full max-w-2xl overflow-y-auto p-8"
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-full p-1.5 text-ink/60 transition-colors hover:bg-cinnabar/20 hover:text-cinnabar"
        >
          <X size={20} />
        </button>

        <div className="mb-4 flex items-center gap-3">
          <MapPin className="text-cinnabar" size={24} />
          <h2 className="font-brush text-4xl text-ink">{marker.name}</h2>
          {visited && (
            <span className="seal flex items-center gap-1">
              <Check size={12} /> 已打卡
            </span>
          )}
        </div>

        <div className="mb-4 flex items-center gap-3 text-sm text-wood">
          <span className="font-serif">{marker.country}</span>
          {dynasty && (
            <>
              <span className="h-px w-6 bg-gold/40" />
              <span className="font-serif">{dynasty.name}</span>
            </>
          )}
        </div>

        <p className="mb-6 font-serif text-sm leading-relaxed text-ink/80">{marker.intro}</p>

        {relics.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-3 font-serif font-semibold text-ink">关联文物 / 建筑</h3>
            <div className="space-y-2">
              {relics.map((r) =>
                r ? (
                  <Link
                    key={r.id}
                    to={`/relics/${r.id}`}
                    className="flex items-center justify-between rounded-lg border border-gold/20 bg-paper-light/50 p-3 transition-colors hover:border-gold hover:bg-gold/10"
                  >
                    <div>
                      <div className="font-serif font-medium text-ink">{r.name}</div>
                      <div className="text-xs text-wood">{r.category} · {r.type}</div>
                    </div>
                    <span className="font-serif text-sm text-gold">查看 →</span>
                  </Link>
                ) : null
              )}
            </div>
          </div>
        )}

        {figures.length > 0 && (
          <div>
            <h3 className="mb-3 font-serif font-semibold text-ink">关联人物</h3>
            <div className="space-y-2">
              {figures.map((f) =>
                f ? (
                  <Link
                    key={f.id}
                    to={`/figures/${f.id}`}
                    className="flex items-center justify-between rounded-lg border border-gold/20 bg-paper-light/50 p-3 transition-colors hover:border-gold hover:bg-gold/10"
                  >
                    <div>
                      <div className="font-serif font-medium text-ink">
                        {f.name}
                        {f.courtesyName && (
                          <span className="ml-2 text-xs text-wood">字 {f.courtesyName}</span>
                        )}
                      </div>
                      <div className="text-xs text-wood">{f.era} · {f.title}</div>
                    </div>
                    <span className="font-serif text-sm text-gold">查看 →</span>
                  </Link>
                ) : null
              )}
            </div>
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}

// ===== 足迹面板 =====
function FootprintPanel({
  visitedIds,
  visitedCountryIds,
  onClose,
}: {
  visitedIds: string[];
  visitedCountryIds: string[];
  onClose: () => void;
}) {
  const visitedMarkersList = markers.filter((m) => visitedIds.includes(m.id));
  const visitedCountriesList = countries.filter((c) => visitedCountryIds.includes(c.id));
  const totalProgress = Math.round(
    ((visitedCountriesList.length + visitedMarkersList.length) / (countries.length + markers.length)) * 100
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="absolute inset-0 z-40 flex items-center justify-center bg-ink-dark/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ x: 50, opacity: 0 }}
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: 50, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
        className="scroll-card relative max-h-[80vh] w-full max-w-xl overflow-y-auto p-8"
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-full p-1.5 text-ink/60 transition-colors hover:bg-cinnabar/20 hover:text-cinnabar"
        >
          <X size={20} />
        </button>

        <div className="mb-6 flex items-center gap-3">
          <Footprints className="text-gold" size={24} />
          <h2 className="font-brush text-4xl text-ink">我的足迹</h2>
        </div>

        {/* 进度环 */}
        <div className="mb-6 flex items-center gap-6">
          <div className="relative h-24 w-24">
            <svg viewBox="0 0 100 100" className="h-full w-full -rotate-90">
              <circle cx="50" cy="50" r="42" fill="none" stroke="#e8dcc0" strokeWidth="8" />
              <circle
                cx="50" cy="50" r="42" fill="none" stroke="#d4a857" strokeWidth="8"
                strokeDasharray={`${2 * Math.PI * 42}`}
                strokeDashoffset={`${2 * Math.PI * 42 * (1 - totalProgress / 100)}`}
                strokeLinecap="round"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="font-brush text-2xl text-gold">{totalProgress}%</span>
              <span className="text-[10px] text-wood">已探索</span>
            </div>
          </div>
          <div className="font-serif text-sm text-ink/70">
            已访问 <span className="font-brush text-2xl text-cinnabar">{visitedCountriesList.length}</span> 国
            <br />
            <span className="font-brush text-2xl text-cinnabar">{visitedMarkersList.length}</span> 处遗址
          </div>
        </div>

        {/* 已访问国家 */}
        {visitedCountriesList.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-2 font-serif font-semibold text-ink">已到访国家</h3>
            <div className="grid grid-cols-2 gap-2">
              {visitedCountriesList.map((c) => (
                <div key={c.id} className="flex items-center gap-2 rounded-lg border border-gold/30 bg-gold/5 p-2">
                  <Check size={14} className="text-gold" />
                  <span className="font-serif text-sm text-ink">{c.name}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 已访问遗址 */}
        {visitedMarkersList.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-2 font-serif font-semibold text-ink">已到访遗址</h3>
            <div className="grid grid-cols-2 gap-2">
              {visitedMarkersList.map((m) => (
                <div key={m.id} className="flex items-center gap-2 rounded-lg border border-gold/30 bg-gold/5 p-2">
                  <Check size={14} className="text-gold" />
                  <span className="font-serif text-sm text-ink">{m.name}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 待探索国家 */}
        {countries.filter((c) => !visitedCountryIds.includes(c.id)).length > 0 && (
          <div>
            <h3 className="mb-2 font-serif font-semibold text-ink/60">待探索国家</h3>
            <div className="grid grid-cols-2 gap-2">
              {countries.filter((c) => !visitedCountryIds.includes(c.id)).map((c) => (
                <div key={c.id} className="flex items-center gap-2 rounded-lg border border-ink/10 bg-ink/5 p-2">
                  <span className="h-2 w-2 rounded-full" style={{ backgroundColor: c.color }} />
                  <span className="font-serif text-sm text-ink/50">{c.name}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}
