export type HotspotType = "hand" | "mouth" | "desk" | "candle" | "books";

interface HotspotDef {
  type: HotspotType;
  position: [number, number, number];
  label: string;
  hint: string;
}

const hotspots: HotspotDef[] = [
  { type: "hand", position: [-0.3, 0.46, 0.52], label: "手", hint: "修身计时" },
  { type: "mouth", position: [-0.1, 1.13, 0.46], label: "口", hint: "修身金句" },
  { type: "books", position: [-0.1, 0.44, 0.55], label: "卷", hint: "典籍推荐" },
  { type: "desk", position: [-0.6, 0.42, 0.1], label: "案", hint: "古籍目录" },
  { type: "candle", position: [0.85, 0.65, 0.15], label: "烛", hint: "历史典故" },
];

function labelOffset(type: HotspotType): [number, number, number] {
  switch (type) {
    case "hand":  return [-0.22, 0.22, 0];
    case "mouth": return [0.2, 0.18, 0];
    case "books": return [0.22, 0.24, 0];
    case "desk":  return [0, 0.28, 0];
    case "candle":return [0, 0.3, 0];
    default:      return [0, 0.28, 0];
  }
}

// 单个热点 —— 默认小圆点，hover 放大
function Hotspot({
  def, active, onHover, onClick,
}: {
  def: HotspotDef;
  active: boolean;
  onHover: (t: HotspotType | null) => void;
  onClick: (t: HotspotType) => void;
}) {
  const ringRef = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);

  useFrame((state) => {
    if (ringRef.current) {
      const t = state.clock.elapsedTime;
      ringRef.current.rotation.z = t * 0.8;
      const s = 1 + Math.sin(t * 2) * 0.15;
      ringRef.current.scale.set(s, s, s);
    }
  });

  const color = active ? "#e6c478" : "#d4a857";

  return (
    <group position={def.position}>
      <mesh
        onPointerOver={(e) => { e.stopPropagation(); setHovered(true); onHover(def.type); document.body.style.cursor = "pointer"; }}
        onPointerOut={() => { setHovered(false); onHover(null); document.body.style.cursor = "auto"; }}
        onClick={(e) => { e.stopPropagation(); onClick(def.type); }}
      >
        <sphereGeometry args={[0.22, 16, 16]} />
        <meshBasicMaterial transparent opacity={0} depthWrite={false} />
      </mesh>
      <mesh ref={ringRef}>
        <ringGeometry args={[0.1, 0.14, 32]} />
        <meshBasicMaterial color={hovered ? "#e6c478" : color} transparent opacity={hovered ? 1 : 0.75} side={THREE.DoubleSide} />
      </mesh>
      <mesh>
        <sphereGeometry args={[0.05, 16, 16]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={hovered ? 3 : 1.5} />
      </mesh>
      <Html
        center
        distanceFactor={5}
        position={labelOffset(def.type)}
        style={{ pointerEvents: "none" }}
        zIndexRange={[10, 0]}
      >
        <div className="flex flex-col items-center gap-1 transition-all duration-200" style={{ opacity: hovered ? 1 : 0.55 }}>
          <div className={`flex items-center justify-center rounded-full font-brush shadow-md transition-all duration-200 ${
            hovered ? "h-9 w-9 bg-gold text-ink-dark shadow-glow text-lg" : "h-6 w-6 bg-ink-dark/85 text-gold border border-gold/50 text-xs"
          }`}>
            {def.label}
          </div>
          {hovered && (
            <div className="whitespace-nowrap rounded-full border border-gold/40 bg-ink-dark/95 px-2 py-0.5 font-serif text-[10px] text-gold backdrop-blur-md">
              {def.hint}
            </div>
          )}
        </div>
      </Html>
    </group>
  );
}

