// 人物画像 URL —— 使用 TRAE API 生成（portrait_4_3 尺寸）
export function portraitUrl(prompt: string): string {
  const trait = figureTraits[prompt];
  if (!trait) return "";
  return `${TRAE_API}?prompt=${encodeURIComponent(trait)}&image_size=portrait_4_3`;
}

// 文物/建筑图片 URL —— 使用 TRAE API 生成（landscape_4_3 尺寸）
export function relicUrl(prompt: string): string {
  const trait = relicTraits[prompt];
  if (!trait) return "";
  return `${TRAE_API}?prompt=${encodeURIComponent(trait)}&image_size=landscape_4_3`;
}

// 书房墙挂画像 URL —— 使用 TRAE API 生成（portrait_4_3 尺寸）
export function wallPortraitUrl(prompt: string): string {
  const trait = figureTraits[prompt];
  if (!trait) return "";
  return `${TRAE_API}?prompt=${encodeURIComponent(trait)}&image_size=portrait_4_3`;
}
