import { useState, useEffect } from "react";
import { relicUrl } from "@/lib/image";

interface RelicThumbProps {
  name: string;
  hue: string;
  type: string;
  category: string;
  size?: "sm" | "md" | "lg";
  imagePrompt?: string; // 文物/建筑描述，用于生成 AI 图片
  onClick?: () => void;
}

const sizeMap = {
  sm: "h-32",
  md: "h-48",
  lg: "h-64",
};

// 文物/建筑缩略图：AI 生图 + 薄材质玻璃框
export default function RelicThumb({
  name,
  hue,
  type,
  category,
  size = "md",
  imagePrompt,
  onClick,
}: RelicThumbProps) {
  const [imgError, setImgError] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const url = imagePrompt ? relicUrl(imagePrompt) : "";
  const showImg = url && !imgError;

  // 加载超时保护：8 秒后自动标记为错误
  useEffect(() => {
    if (!showImg) return;
    const timer = setTimeout(() => {
      if (!imgLoaded) setImgError(true);
    }, 8000);
    return () => clearTimeout(timer);
  }, [showImg, imgLoaded]);

  return (
    <div
      onClick={onClick}
      className={`relative ${sizeMap[size]} w-full overflow-hidden rounded-lg cursor-pointer group`}
      style={{
        background: showImg
          ? `linear-gradient(135deg, ${hue}44 0%, ${hue}22 100%)`
          : `linear-gradient(135deg, ${hue}aa 0%, ${hue}66 50%, ${hue}44 100%)`,
        boxShadow: `0 2px 16px ${hue}25, inset 0 0 30px rgba(0,0,0,0.12)`,
        border: "1px solid rgba(255,255,255,0.1)",
      }}
    >
      {/* AI 生图 */}
      {showImg && (
        <>
          {!imgLoaded && (
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="font-serif text-xs text-paper/40">加载中...</div>
            </div>
          )}
          <img
            src={url}
            alt={name}
            loading="lazy"
            onLoad={() => setImgLoaded(true)}
            onError={() => setImgError(true)}
            className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-700 ${
              imgLoaded ? "opacity-85" : "opacity-0"
            }`}
          />
        </>
      )}

      {/* 薄材质玻璃覆层 */}
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-white/5" />
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-15" />

      {/* 装饰边框 - 薄边 */}
      <div className="absolute inset-2 rounded border border-white/10" />

      {/* 类型印章 */}
      <div className="absolute left-3 top-3">
        <span className="seal backdrop-blur-sm">{type}</span>
      </div>

      {/* 底部标题 - 薄材质渐变 */}
      <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-ink-dark/80 via-ink-dark/30 to-transparent p-3 pt-8 backdrop-blur-[2px]">
        <div className="font-serif font-semibold text-paper-light drop-shadow">{name}</div>
        <div className="mt-0.5 text-xs text-gold/80">{category}</div>
      </div>

      {/* 悬停效果 - 薄光 */}
      <div className="pointer-events-none absolute inset-0 bg-gold/0 transition-all duration-500 group-hover:bg-gold/8" />
      <div className="pointer-events-none absolute inset-3 rounded border border-gold/0 transition-all duration-500 group-hover:border-gold/40" />
    </div>
  );
}
