import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { portraitUrl } from "@/lib/image";

interface FigurePortraitProps {
  name: string;
  title?: string;
  hue: string;
  size?: "sm" | "md" | "lg" | "xl";
  imagePrompt?: string; // 画像描述，用于生成 AI 图片
  onClick?: () => void;
}

const sizeMap = {
  sm: "h-24 w-20",
  md: "h-36 w-28",
  lg: "h-52 w-40",
  xl: "h-80 w-60",
};

const fontSizeMap = {
  sm: "text-lg",
  md: "text-2xl",
  lg: "text-3xl",
  xl: "text-5xl",
};

// 人物画像：AI 生图 + 薄材质玻璃框
export default function FigurePortrait({
  name,
  title,
  hue,
  size = "md",
  imagePrompt,
  onClick,
}: FigurePortraitProps) {
  const [imgError, setImgError] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const url = imagePrompt ? portraitUrl(imagePrompt) : "";
  const showImg = url && !imgError;

  // 加载超时保护：8 秒后自动标记为错误
  useEffect(() => {
    if (!showImg) return;
    const timer = setTimeout(() => {
      if (!imgLoaded) setImgError(true);
    }, 8000);
    return () => clearTimeout(timer);
  }, [showImg, imgLoaded]);

  return (
    <div
      onClick={onClick}
      className={`relative ${sizeMap[size]} overflow-hidden rounded-t-full rounded-b-md cursor-pointer group`}
      style={{
        background: showImg
          ? `linear-gradient(180deg, ${hue}33 0%, ${hue}22 100%)`
          : `linear-gradient(180deg, ${hue}cc 0%, ${hue}88 40%, ${hue}55 100%)`,
        boxShadow: `0 0 20px ${hue}30, inset 0 0 20px rgba(0,0,0,0.15)`,
        border: "1px solid rgba(255,255,255,0.12)",
      }}
    >
      {/* AI 生图 */}
      {showImg && (
        <>
          {!imgLoaded && (
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="font-serif text-[10px] text-paper/40">加载中...</div>
            </div>
          )}
          <img
            src={url}
            alt={name}
            loading="lazy"
            onLoad={() => setImgLoaded(true)}
            onError={() => setImgError(true)}
            className={`absolute inset-0 h-full w-full object-cover transition-opacity duration-700 ${
              imgLoaded ? "opacity-90" : "opacity-0"
            }`}
          />
        </>
      )}

      {/* 薄材质玻璃覆层 */}
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-b from-white/5 via-transparent to-black/20" />

      {/* 顶部留白如卷轴 */}
      <div className="absolute inset-x-0 top-0 h-3 bg-ink-dark/30" />
      <div className="absolute inset-x-0 bottom-0 h-2 bg-cinnabar/50" />

      {/* 人物名印 */}
      <div className="absolute inset-0 flex flex-col items-center justify-end gap-1.5 pb-4">
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className={`font-brush ${fontSizeMap[size]} text-paper-light text-shadow-soft drop-shadow-lg`}
          style={{ writingMode: "vertical-rl" }}
        >
          {name}
        </motion.div>
        {title && size !== "sm" && (
          <div className="rounded bg-cinnabar/70 px-2 py-0.5 font-serif text-[10px] tracking-wider text-paper-light backdrop-blur-sm">
            {title}
          </div>
        )}
      </div>

      {/* 装饰纹理 */}
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-20" />

      {/* 悬停光晕 */}
      <div
        className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-500 group-hover:opacity-100"
        style={{ background: `radial-gradient(circle at center, ${hue}44 0%, transparent 70%)` }}
      />
    </div>
  );
}
