import { useState } from "react";
import { Link } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";
import NavBar from "@/components/NavBar";
import { dynasties, figures, relics, type Dynasty } from "@/data";
import { portraitUrl, relicUrl } from "@/lib/image";

// 按时间排序
const sorted = [...dynasties].sort((a, b) => a.startYear - b.startYear);
const minYear = sorted[0].startYear;
const maxYear = sorted[sorted.length - 1].endYear;
const totalSpan = maxYear - minYear;

const chinaDynasties = sorted.filter((d) => d.country === "中国");
const worldDynasties = sorted.filter((d) => d.country === "世界");

function yearLabel(y: number): string {
  return y < 0 ? `公元前${-y}` : `公元${y}`;
}

function dynastyWidth(d: Dynasty): number {
  return Math.max(((d.endYear - d.startYear) / totalSpan) * 100, 3);
}

function dynastyPos(d: Dynasty): number {
  return ((d.startYear - minYear) / totalSpan) * 100;
}

export default function Timeline() {
  const [selected, setSelected] = useState<Dynasty | null>(null);

  return (
    <div className="relative min-h-screen overflow-x-hidden bg-ink-wash">
      {/* 背景图 */}
      <div
        className="pointer-events-none absolute inset-0 bg-cover bg-center bg-no-repeat opacity-25"
        style={{ backgroundImage: "url(/history-bg.png)" }}
      />
      {/* 背景纹理叠加 */}
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-20" />
      {/* 渐变遮罩，保证文字可读 */}
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-b from-ink-dark/60 via-transparent to-ink-dark/80" />

      <NavBar />

      {/* 标题 */}
      <div className="px-6 pt-32 pb-12 text-center">
        <motion.h1
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="font-brush text-6xl text-gold text-glow-gold"
        >
          历史长河
        </motion.h1>
        <p className="mt-3 font-serif text-paper/60">
          中外朝代并置 · {yearLabel(minYear)} — {yearLabel(maxYear)}
        </p>
      </div>

      {/* 时间标尺 */}
      <div className="mx-auto max-w-7xl px-6 pb-20">
        {/* 年份刻度 */}
        <div className="relative mb-2 h-6">
          {[-2000, -1000, 0, 1000, 2000].map((y) => {
            if (y < minYear || y > maxYear) return null;
            const pos = ((y - minYear) / totalSpan) * 100;
            return (
              <div
                key={y}
                className="absolute -translate-x-1/2 font-serif text-xs text-paper/40"
                style={{ left: `${pos}%` }}
              >
                <div className="mb-1 h-2 w-px bg-gold/30" />
                {yearLabel(y)}
              </div>
            );
          })}
        </div>

        {/* 中国朝代 */}
        <div className="mb-8">
          <div className="mb-3 flex items-center gap-3">
            <span className="seal">中国</span>
            <div className="h-px flex-1 bg-gold/20" />
          </div>
          <div className="relative h-20">
            <div className="absolute inset-x-0 top-1/2 h-px bg-gold/20" />
            {chinaDynasties.map((d, i) => {
              const pos = dynastyPos(d);
              const width = dynastyWidth(d);
              return (
                <motion.div
                  key={d.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                  className="absolute top-1/2 -translate-y-1/2"
                  style={{ left: `${pos}%`, width: `${width}%` }}
                >
                  <button
                    onClick={() => setSelected(d)}
                    className="group relative block w-full overflow-hidden rounded-md border border-gold/30 px-2 py-2 transition-all hover:border-gold hover:shadow-glow"
                    style={{ backgroundColor: `${d.color}40` }}
                  >
                    <div
                      className="absolute inset-0 opacity-50"
                      style={{ background: `linear-gradient(90deg, ${d.color}80, ${d.color}40)` }}
                    />
                    <div className="relative font-brush text-lg text-paper-light">{d.name}</div>
                    <div className="relative font-serif text-[10px] text-paper/60">
                      {d.startYear < 0 ? -d.startYear + "BC" : d.startYear + "AD"}-
                      {d.endYear < 0 ? -d.endYear + "BC" : d.endYear + "AD"}
                    </div>
                  </button>
                </motion.div>
              );
            })}
          </div>
        </div>

        {/* 世界文明 */}
        <div>
          <div className="mb-3 flex items-center gap-3">
            <span className="seal" style={{ backgroundColor: "#4a90c4" }}>世界</span>
            <div className="h-px flex-1 bg-gold/20" />
          </div>
          <div className="relative h-20">
            <div className="absolute inset-x-0 top-1/2 h-px bg-gold/20" />
            {worldDynasties.map((d, i) => {
              const pos = dynastyPos(d);
              const width = dynastyWidth(d);
              return (
                <motion.div
                  key={d.id}
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                  className="absolute top-1/2 -translate-y-1/2"
                  style={{ left: `${pos}%`, width: `${width}%` }}
                >
                  <button
                    onClick={() => setSelected(d)}
                    className="group relative block w-full overflow-hidden rounded-md border border-gold/30 px-2 py-2 transition-all hover:border-gold hover:shadow-glow"
                    style={{ backgroundColor: `${d.color}40` }}
                  >
                    <div
                      className="absolute inset-0 opacity-50"
                      style={{ background: `linear-gradient(90deg, ${d.color}80, ${d.color}40)` }}
                    />
                    <div className="relative font-brush text-lg text-paper-light">{d.name}</div>
                    <div className="relative font-serif text-[10px] text-paper/60">
                      {d.startYear < 0 ? -d.startYear + "BC" : d.startYear + "AD"}-
                      {d.endYear < 0 ? -d.endYear + "BC" : d.endYear + "AD"}
                    </div>
                  </button>
                </motion.div>
              );
            })}
          </div>
        </div>
      </div>

      {/* 详情弹窗 */}
      <AnimatePresence>
        {selected && (
          <DynastyPopup dynasty={selected} onClose={() => setSelected(null)} />
        )}
      </AnimatePresence>
    </div>
  );
}

function DynastyPopup({ dynasty, onClose }: { dynasty: Dynasty; onClose: () => void }) {
  const eraFigures = figures.filter((f) => f.dynastyId === dynasty.id);
  const eraRelics = relics.filter((r) => r.dynastyId === dynasty.id);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-40 flex items-center justify-center bg-ink-dark/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.9, y: 20 }}
        animate={{ scale: 1, y: 0 }}
        exit={{ scale: 0.9, y: 20 }}
        onClick={(e) => e.stopPropagation()}
        className="scroll-card relative max-h-[85vh] w-full max-w-3xl overflow-y-auto p-8"
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-full p-1.5 text-ink/60 transition-colors hover:bg-cinnabar/20 hover:text-cinnabar"
        >
          <X size={20} />
        </button>

        <div className="mb-6 flex items-center gap-4">
          <div
            className="flex h-14 w-14 items-center justify-center rounded-full font-brush text-2xl"
            style={{ backgroundColor: `${dynasty.color}40`, color: dynasty.color }}
          >
            {dynasty.name.slice(0, 1)}
          </div>
          <div>
            <h2 className="font-brush text-5xl text-ink">{dynasty.name}</h2>
            <div className="font-serif text-sm text-wood">
              {yearLabel(dynasty.startYear)} — {yearLabel(dynasty.endYear)} · {dynasty.country}
            </div>
          </div>
        </div>

        <p className="mb-6 font-serif text-sm leading-relaxed text-ink/80">{dynasty.intro}</p>

        {/* 时代背景 - 装饰性背景段落 */}
        {dynasty.background && (
          <div
            className="relative mb-6 overflow-hidden rounded-lg border border-gold/20 p-5"
            style={{ background: `linear-gradient(135deg, ${dynasty.color}18, ${dynasty.color}06)` }}
          >
            <div className="pointer-events-none absolute inset-0 bg-grain opacity-10" />
            <div className="pointer-events-none absolute right-3 top-1 font-brush text-7xl text-ink/5 select-none">
              史
            </div>
            <div className="relative">
              <div className="mb-2 flex items-center gap-2">
                <div className="h-px w-6" style={{ backgroundColor: dynasty.color }} />
                <span className="font-brush text-base" style={{ color: dynasty.color }}>
                  时代背景
                </span>
                <div className="h-px flex-1 bg-gold/20" />
              </div>
              <p className="font-serif text-sm leading-loose text-ink/75">
                {dynasty.background}
              </p>
            </div>
          </div>
        )}

        {/* 代表人物 */}
        {eraFigures.length > 0 && (
          <div className="mb-6">
            <h3 className="mb-3 font-serif font-semibold text-ink">代表人物</h3>
            <div className="grid grid-cols-2 gap-3 md:grid-cols-3">
              {eraFigures.map((f) => (
                <Link
                  key={f.id}
                  to={`/figures/${f.id}`}
                  className="flex items-center gap-3 rounded-lg border border-gold/20 bg-paper-light/50 p-3 transition-colors hover:border-gold hover:bg-gold/10"
                >
                  <div
                    className="relative h-12 w-10 overflow-hidden rounded flex-shrink-0"
                    style={{ backgroundColor: f.imageHue }}
                  >
                    <img
                      src={portraitUrl(f.image)}
                      alt={f.name}
                      loading="lazy"
                      className="absolute inset-0 h-full w-full object-cover opacity-85"
                      onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
                      onLoad={(e) => { if (!portraitUrl(f.image)) (e.target as HTMLImageElement).style.display = 'none'; }}
                    />
                    <div className="absolute inset-0 flex items-center justify-center font-brush text-sm text-paper-light">
                      {f.name.slice(0, 1)}
                    </div>
                  </div>
                  <div>
                    <div className="font-serif font-medium text-ink">{f.name}</div>
                    <div className="text-xs text-wood">{f.title}</div>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}

        {/* 代表文物 */}
        {eraRelics.length > 0 && (
          <div>
            <h3 className="mb-3 font-serif font-semibold text-ink">代表文物 / 建筑</h3>
            <div className="grid grid-cols-2 gap-3 md:grid-cols-3">
              {eraRelics.map((r) => (
                <Link
                  key={r.id}
                  to={`/relics/${r.id}`}
                  className="rounded-lg border border-gold/20 bg-paper-light/50 p-3 transition-colors hover:border-gold hover:bg-gold/10"
                >
                  <div
                    className="relative mb-2 h-16 overflow-hidden rounded"
                    style={{ background: `linear-gradient(135deg, ${r.imageHue}aa, ${r.imageHue}55)` }}
                  >
                    <img
                      src={relicUrl(r.name)}
                      alt={r.name}
                      loading="lazy"
                      className="absolute inset-0 h-full w-full object-cover opacity-80"
                      onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
                    />
                  </div>
                  <div className="font-serif font-medium text-ink">{r.name}</div>
                  <div className="text-xs text-wood">{r.type} · {r.category}</div>
                </Link>
              ))}
            </div>
          </div>
        )}

        {eraFigures.length === 0 && eraRelics.length === 0 && (
          <div className="rounded-lg border border-gold/20 bg-paper-light/30 p-6 text-center font-serif text-sm text-ink/60">
            该时代数据正在补充中...
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}
