import { useState } from "react";
import { motion } from "framer-motion";
import NavBar from "@/components/NavBar";
import FigurePortrait from "@/components/FigurePortrait";
import { figures, dynasties } from "@/data";

const countries = [
  { id: "all", label: "全部" },
  { id: "中国", label: "中国" },
  { id: "世界", label: "世界" },
];

export default function Figures() {
  const [country, setCountry] = useState<string>("all");
  const [dynastyId, setDynastyId] = useState<string>("all");

  const filtered = figures.filter((f) => {
    if (country !== "all" && f.country !== country) return false;
    if (dynastyId !== "all" && f.dynastyId !== dynastyId) return false;
    return true;
  });

  const availableDynasties = dynasties.filter((d) =>
    figures.some((f) => f.dynastyId === d.id)
  );

  return (
    <div className="relative min-h-screen bg-ink-wash">
      <div className="pointer-events-none absolute inset-0 bg-grain opacity-20" />

      <NavBar />

      <div className="px-6 pt-32 pb-12 text-center">
        <motion.h1
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="font-brush text-6xl text-gold text-glow-gold"
        >
          人物图鉴
        </motion.h1>
        <p className="mt-3 font-serif text-paper/60">中外历史圣贤群像 · 悬停查看简介</p>
      </div>

      {/* 筛选器 */}
      <div className="mx-auto mb-10 max-w-6xl px-6">
        <div className="flex flex-wrap items-center justify-center gap-3">
          <div className="flex items-center gap-1 rounded-full border border-gold/30 bg-ink-dark/50 p-1">
            {countries.map((c) => (
              <button
                key={c.id}
                onClick={() => setCountry(c.id)}
                className={`rounded-full px-4 py-1.5 font-serif text-sm transition-all ${
                  country === c.id
                    ? "bg-gold-gradient text-ink-dark"
                    : "text-paper/70 hover:text-gold"
                }`}
              >
                {c.label}
              </button>
            ))}
          </div>

          <select
            value={dynastyId}
            onChange={(e) => setDynastyId(e.target.value)}
            className="rounded-full border border-gold/30 bg-ink-dark/50 px-4 py-2 font-serif text-sm text-paper outline-none backdrop-blur-md"
          >
            <option value="all">全部朝代</option>
            {availableDynasties.map((d) => (
              <option key={d.id} value={d.id} className="bg-ink-dark">
                {d.country} · {d.name}
              </option>
            ))}
          </select>

          <span className="rounded-full bg-gold/10 px-3 py-1.5 font-serif text-xs text-gold">
            共 {filtered.length} 位
          </span>
        </div>
      </div>

      {/* 人物墙 */}
      <div className="mx-auto max-w-6xl px-6 pb-24">
        <div className="grid grid-cols-2 gap-6 md:grid-cols-3 lg:grid-cols-4">
          {filtered.map((f, i) => (
            <motion.div
              key={f.id}
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              <FigureCard figure={f} />
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { Link } from "react-router-dom";
import { getDynasty, type Figure } from "@/data";

function FigureCard({ figure }: { figure: Figure }) {
  const dynasty = getDynasty(figure.dynastyId);
  const [flipped, setFlipped] = useState(false);

  return (
    <div
      className="group relative cursor-pointer"
      onMouseEnter={() => setFlipped(true)}
      onMouseLeave={() => setFlipped(false)}
    >
      <Link to={`/figures/${figure.id}`}>
        <div className="relative" style={{ perspective: "1000px" }}>
          <div
            className="relative transition-transform duration-700"
            style={{
              transformStyle: "preserve-3d",
              transform: flipped ? "rotateY(180deg)" : "",
            }}
          >
            {/* 正面 */}
            <div style={{ backfaceVisibility: "hidden" }}>
              <FigurePortrait
                name={figure.name}
                title={figure.title}
                hue={figure.imageHue}
                size="lg"
                imagePrompt={figure.image}
              />
              {/* 朝代标签 */}
              <div className="mt-2 flex items-center justify-between">
                <span
                  className="rounded-full px-2 py-0.5 font-serif text-[10px]"
                  style={{
                    backgroundColor: `${dynasty?.color}30`,
                    color: dynasty?.color,
                  }}
                >
                  {dynasty?.name}
                </span>
                <span className="font-serif text-[10px] text-paper/50">{figure.era}</span>
              </div>
            </div>

            {/* 背面 */}
            <div
              className="absolute inset-0 flex flex-col items-center justify-center rounded-t-full rounded-b-md border border-gold/40 bg-ink-dark/95 p-4 text-center"
              style={{
                backfaceVisibility: "hidden",
                transform: "rotateY(180deg)",
              }}
            >
              <div className="font-brush text-3xl text-gold">{figure.name}</div>
              <div className="mt-1 font-serif text-xs text-cinnabar">{figure.title}</div>
              <div className="mt-3 h-px w-12 bg-gold/40" />
              <p className="mt-3 font-serif text-[11px] leading-relaxed text-paper/70 line-clamp-6">
                {figure.bio}
              </p>
              <div className="mt-3 font-serif text-[10px] text-gold">点击查看详情 →</div>
            </div>
          </div>
        </div>
      </Link>
    </div>
  );
}
