import { useRef, useState, useMemo, Suspense } from "react";
import { Canvas, useFrame, useLoader } from "@react-three/fiber";
import { OrbitControls, Stars, Html } from "@react-three/drei";
import * as THREE from "three";
import { markers, countries, type Marker, type Country } from "@/data";

// 真实地球贴图 CDN（jsdelivr 支持 CORS）
const EARTH_DAY = "https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_atmos_2048.jpg";
const EARTH_NORMAL = "https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_normal_2048.jpg";
const EARTH_SPEC = "https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_specular_2048.jpg";
const CLOUDS = "https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_clouds_1024.png";

// 经纬度转 3D 坐标
function latLngToVector3(lat: number, lng: number, radius: number): THREE.Vector3 {
  const phi = (90 - lat) * (Math.PI / 180);
  const theta = (lng + 180) * (Math.PI / 180);
  return new THREE.Vector3(
    -radius * Math.sin(phi) * Math.cos(theta),
    radius * Math.cos(phi),
    radius * Math.sin(phi) * Math.sin(theta)
  );
}

// 真实贴图地球
function RealEarth({ earthRef }: { earthRef: React.RefObject<THREE.Mesh> }) {
  const [dayMap, normalMap, specMap, cloudMap] = useLoader(THREE.TextureLoader, [
    EARTH_DAY,
    EARTH_NORMAL,
    EARTH_SPEC,
    CLOUDS,
  ]);

  const cloudsRef = useRef<THREE.Mesh>(null);

  useFrame((_, delta) => {
    if (earthRef.current) {
      earthRef.current.rotation.y += delta * 0.04;
    }
    if (cloudsRef.current) {
      cloudsRef.current.rotation.y += delta * 0.05;
    }
  });

  return (
    <group>
      {/* 地球主体 */}
      <mesh ref={earthRef}>
        <sphereGeometry args={[2, 64, 64]} />
        <meshPhongMaterial
          map={dayMap}
          normalMap={normalMap}
          specularMap={specMap}
          shininess={15}
          specular={new THREE.Color("#222244")}
        />
      </mesh>

      {/* 云层 */}
      <mesh ref={cloudsRef}>
        <sphereGeometry args={[2.03, 64, 64]} />
        <meshPhongMaterial
          map={cloudMap}
          transparent
          opacity={0.4}
          depthWrite={false}
        />
      </mesh>

      {/* 大气辉光 */}
      <mesh>
        <sphereGeometry args={[2.18, 32, 32]} />
        <meshBasicMaterial
          color="#4a90c4"
          transparent
          opacity={0.15}
          side={THREE.BackSide}
        />
      </mesh>
    </group>
  );
}

// 加载占位（地球纹理下载时显示）
function EarthFallback({ earthRef }: { earthRef: React.RefObject<THREE.Mesh> }) {
  useFrame((_, delta) => {
    if (earthRef.current) {
      earthRef.current.rotation.y += delta * 0.04;
    }
  });
  return (
    <mesh ref={earthRef}>
      <sphereGeometry args={[2, 32, 32]} />
      <meshStandardMaterial color="#1e3a5f" emissive="#0a1628" emissiveIntensity={0.3} />
    </mesh>
  );
}

// 标记点 + 光柱
function Marker3D({
  marker,
  visited,
  onHover,
  onClick,
  earthRef,
}: {
  marker: Marker;
  visited: boolean;
  onHover: (m: Marker | null) => void;
  onClick: (m: Marker) => void;
  earthRef: React.RefObject<THREE.Mesh>;
}) {
  const groupRef = useRef<THREE.Group>(null);
  const beamRef = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);
  const basePos = useMemo(() => latLngToVector3(marker.lat, marker.lng, 2.05), [marker.lat, marker.lng]);

  useFrame((state) => {
    if (groupRef.current && earthRef.current) {
      groupRef.current.rotation.y = earthRef.current.rotation.y;
    }
    if (beamRef.current) {
      const pulse = 1 + Math.sin(state.clock.elapsedTime * 2) * 0.25;
      beamRef.current.scale.y = pulse;
    }
  });

  // 中国红色、外国蓝色、已访问金色
  const color = visited
    ? "#d4a857"
    : marker.country === "中国"
      ? "#c8423f"
      : "#4a90c4";

  return (
    <group ref={groupRef}>
      <group position={basePos}>
        {/* 标记球（加大可点击区域） */}
        <mesh
          onPointerOver={(e) => {
            e.stopPropagation();
            setHovered(true);
            onHover(marker);
            document.body.style.cursor = "pointer";
          }}
          onPointerOut={() => {
            setHovered(false);
            onHover(null);
            document.body.style.cursor = "auto";
          }}
          onClick={(e) => {
            e.stopPropagation();
            onClick(marker);
          }}
        >
          <sphereGeometry args={[0.06, 16, 16]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={hovered ? 2.5 : 1.5}
          />
        </mesh>

        {/* 光柱 */}
        <mesh ref={beamRef} position={[0, 0.18, 0]}>
          <cylinderGeometry args={[0.02, 0.02, 0.36, 8]} />
          <meshBasicMaterial color={color} transparent opacity={0.6} />
        </mesh>

        {/* 悬停光圈 */}
        {hovered && (
          <mesh>
            <ringGeometry args={[0.08, 0.11, 32]} />
            <meshBasicMaterial color="#d4a857" transparent opacity={0.8} side={THREE.DoubleSide} />
          </mesh>
        )}

        {/* 名称标签 */}
        {hovered && (
          <Html center distanceFactor={6} position={[0, 0.4, 0]} zIndexRange={[10, 0]}>
            <div className="whitespace-nowrap rounded-full border border-gold/40 bg-ink-dark/90 px-3 py-1 font-serif text-xs text-gold backdrop-blur-md">
              {marker.name}
            </div>
          </Html>
        )}
      </group>
    </group>
  );
}

interface GlobeSceneProps {
  onMarkerClick: (m: Marker) => void;
  onMarkerHover: (m: Marker | null) => void;
  visitedIds: string[];
  onCountryClick?: (c: Country) => void;
  onCountryHover?: (c: Country | null) => void;
  visitedCountryIds?: string[];
  showCountries?: boolean;
}

// 国家板块标记（大号发光区域 + 始终显示国名）
function Country3D({
  country,
  visited,
  onHover,
  onClick,
  earthRef,
}: {
  country: Country;
  visited: boolean;
  onHover: (c: Country | null) => void;
  onClick: (c: Country) => void;
  earthRef: React.RefObject<THREE.Mesh>;
}) {
  const groupRef = useRef<THREE.Group>(null);
  const ringRef = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);
  const basePos = useMemo(() => latLngToVector3(country.lat, country.lng, 2.06), [country.lat, country.lng]);

  useFrame((state) => {
    if (groupRef.current && earthRef.current) {
      groupRef.current.rotation.y = earthRef.current.rotation.y;
    }
    if (ringRef.current) {
      ringRef.current.rotation.z = state.clock.elapsedTime * 0.5;
      const s = 1 + Math.sin(state.clock.elapsedTime * 1.5) * 0.12;
      ringRef.current.scale.set(s, s, s);
    }
  });

  const color = country.color;

  return (
    <group ref={groupRef}>
      <group position={basePos}>
        {/* 大透明可点击区域 */}
        <mesh
          onPointerOver={(e) => { e.stopPropagation(); setHovered(true); onHover(country); document.body.style.cursor = "pointer"; }}
          onPointerOut={() => { setHovered(false); onHover(null); document.body.style.cursor = "auto"; }}
          onClick={(e) => { e.stopPropagation(); onClick(country); }}
        >
          <sphereGeometry args={[0.15, 16, 16]} />
          <meshBasicMaterial transparent opacity={0} depthWrite={false} />
        </mesh>

        {/* 标记球 */}
        <mesh>
          <sphereGeometry args={[0.08, 16, 16]} />
          <meshStandardMaterial
            color={visited ? "#d4a857" : color}
            emissive={visited ? "#d4a857" : color}
            emissiveIntensity={hovered ? 3 : 2}
          />
        </mesh>

        {/* 光柱 */}
        <mesh position={[0, 0.22, 0]}>
          <cylinderGeometry args={[0.03, 0.03, 0.44, 8]} />
          <meshBasicMaterial color={visited ? "#d4a857" : color} transparent opacity={0.6} />
        </mesh>

        {/* 旋转光圈 */}
        <mesh ref={ringRef}>
          <ringGeometry args={[0.12, 0.16, 32]} />
          <meshBasicMaterial color={hovered ? "#e6c478" : (visited ? "#d4a857" : color)} transparent opacity={hovered ? 1 : 0.7} side={THREE.DoubleSide} />
        </mesh>

        {/* 始终显示国名标签 */}
        <Html center distanceFactor={7} position={[0, 0.42, 0]} style={{ pointerEvents: "none" }} zIndexRange={[10, 0]}>
          <div
            className="whitespace-nowrap rounded-full border px-2.5 py-0.5 font-serif text-[11px] backdrop-blur-md transition-all"
            style={{
              borderColor: hovered ? "#e6c478" : `${color}80`,
              backgroundColor: "rgba(15,8,4,0.85)",
              color: hovered ? "#e6c478" : (visited ? "#d4a857" : "#f4ecd8"),
              boxShadow: hovered ? "0 0 10px rgba(212,168,87,0.4)" : "none",
            }}
          >
            {country.name}
          </div>
        </Html>
      </group>
    </group>
  );
}

function Scene({ onMarkerClick, onMarkerHover, visitedIds, onCountryClick, onCountryHover, visitedCountryIds = [], showCountries = true }: GlobeSceneProps) {
  const earthRef = useRef<THREE.Mesh>(null);

  return (
    <>
      <ambientLight intensity={0.6} />
      <directionalLight position={[5, 3, 5]} intensity={1.5} color="#fff5e0" />
      <pointLight position={[-5, -2, -3]} intensity={0.4} color="#4a90c4" />

      <Stars radius={50} depth={20} count={3000} factor={2} fade speed={0.5} />

      <Suspense fallback={<EarthFallback earthRef={earthRef} />}>
        <RealEarth earthRef={earthRef} />
      </Suspense>

      {/* 国家板块标记（默认显示） */}
      {showCountries && onCountryClick && countries.map((c) => (
        <Country3D
          key={c.id}
          country={c}
          visited={visitedCountryIds.includes(c.id)}
          onHover={onCountryHover || (() => {})}
          onClick={onCountryClick}
          earthRef={earthRef}
        />
      ))}

      {/* 细节标记点（仅当不显示国家模式时显示） */}
      {!showCountries && markers.map((m) => (
        <Marker3D
          key={m.id}
          marker={m}
          visited={visitedIds.includes(m.id)}
          onHover={onMarkerHover}
          onClick={onMarkerClick}
          earthRef={earthRef}
        />
      ))}

      <OrbitControls
        enablePan={false}
        minDistance={3}
        maxDistance={8}
        enableDamping
        dampingFactor={0.05}
      />
    </>
  );
}

export default function GlobeSceneWrapper(props: GlobeSceneProps) {
  return (
    <Canvas camera={{ position: [0, 0, 5], fov: 50 }} dpr={[1, 2]}>
      <Scene {...props} />
    </Canvas>
  );
}
